export function checklistPorNorma(norma: string, tipo?: string): ItemChecklist[] {
  // Auditorías internas que cubren ambas normas usan la lista de verificación oficial
  // por proceso (FSG-57), más completa que la concatenación genérica.
  if (tipo === 'interna' && norma === 'ambas') return CHECKLIST_INTERNA_AMBAS_NORMAS
  if (norma === 'iso_9001') return CHECKLIST_ISO_9001
  if (norma === 'sqf') return CHECKLIST_SQF
  if (norma === 'ambas') return [...CHECKLIST_ISO_9001, ...CHECKLIST_SQF]
  return []
}
